using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class ReportMarkings {
 public static string Main(){bool reverse=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name.EndsWith("Reverse");var road=Object.FindAnyObjectByType<RaceDirector>().road;road.Initialize();var pavement=GameObject.Find("Ground_CR133 mountain driving surface").GetComponent<MeshCollider>();var notes=new List<string>();Material arrowMaterial=null;int edited=0;
 foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&(m.name.IndexOf("arrow",StringComparison.OrdinalIgnoreCase)>=0||m.name.Contains("Main teal"))).ToArray()){
 var verts=mf.sharedMesh.vertices;var ix=mf.sharedMesh.triangles;var parents=Enumerable.Range(0,verts.Length).ToArray();int Find(int i){while(parents[i]!=i){parents[i]=parents[parents[i]];i=parents[i];}return i;}void Join(int a,int b){parents[Find(a)]=Find(b);}var weld=new Dictionary<Vector3Int,int>();for(int i=0;i<verts.Length;i++){var key=Vector3Int.RoundToInt(verts[i]*1000);if(weld.TryGetValue(key,out var j))Join(i,j);else weld[key]=i;}for(int i=0;i<ix.Length;i+=3){Join(ix[i],ix[i+1]);Join(ix[i],ix[i+2]);}
 var remove=new HashSet<int>();foreach(var group in ix.Distinct().GroupBy(Find)){var points=group.Select(i=>mf.transform.TransformPoint(verts[i])).ToArray();if(points.Length>200||points.Length<7)continue;var p=points.Aggregate(Vector3.zero,(a,b)=>a+b)/points.Length;var bounds=new Bounds(p,Vector3.zero);foreach(var q in points)bounds.Encapsulate(q);if(bounds.size.magnitude>20)continue;
 bool obsolete=reverse&&p.x>850&&p.x<910&&p.z> -80&&p.z< -28&&!pavement.Raycast(new Ray(p+Vector3.up*4,Vector3.down),out _,8);
 bool bend=!reverse&&Vector2.Distance(new(p.x,p.z),new(1344.49f,-271.02f))<18;
 if(!obsolete&&!bend)continue;remove.Add(group.Key);notes.Add("Removed "+(obsolete?"unsupported legacy marking ":"bend marking ")+mf.name+" at "+p);if(bend)arrowMaterial=mf.GetComponent<Renderer>().sharedMaterial;
 }
 if(remove.Count==0)continue;var keep=new List<int>();for(int i=0;i<ix.Length;i+=3)if(!remove.Contains(Find(ix[i])))keep.AddRange(new[]{ix[i],ix[i+1],ix[i+2]});var mesh=Object.Instantiate(mf.sharedMesh);mesh.triangles=keep.ToArray();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Track/ReportCleanup/"+(reverse?"reverse":"forward")+"-retained-markings-"+edited+++".asset");mf.sharedMesh=mesh;
 }
 if(arrowMaterial){float station=760;for(;station<875;station+=2){road.At(station,out var a);road.At(station+12,out var b);if(Vector3.Angle(Vector3.ProjectOnPlane(a,Vector3.up),Vector3.ProjectOnPlane(b,Vector3.up))<4)break;}var center=road.At(station,out var forward);forward=Vector3.ProjectOnPlane(forward,Vector3.up).normalized;var right=Vector3.Cross(Vector3.up,forward);var shape=new[]{new Vector2(-.44f,-3),new(.44f,-3),new(.44f,0),new(1.1f,0),new(0,3),new(-1.1f,0),new(-.44f,0)};var vertices=shape.Select(v=>{var p=center+right*v.x+forward*v.y;if(pavement.Raycast(new Ray(p+Vector3.up*4,Vector3.down),out var hit,8))p.y=hit.point.y+.10f;return p;}).ToArray();var mesh=new Mesh{vertices=vertices,triangles=new[]{0,6,1,1,6,2,6,5,4,6,4,2,2,4,3}};mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Track/ReportCleanup/forward-after-bend-arrow.asset");var go=new GameObject("Main teal arrow after bend",typeof(MeshFilter),typeof(MeshRenderer));go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<Renderer>().sharedMaterial=arrowMaterial;notes.Add("Placed following-straight arrow at station "+station+" / "+center);}
 EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();File.WriteAllLines("Docs/ReportCleanup/"+(reverse?"reverse":"forward")+"-markings.txt",notes);return string.Join("\n",notes);
 }
}
